/**
 * @name XML Injection via Formatting
 * @description Checking if user input flows into manual XML string formatting
 * @kind path-problem
 * @problem.severity error
 * @id py/xml-injection-formatting-flow
 * @tags security
 *       external/cwe/cwe-116
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module XmlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters of public methods/functions
    exists(Function f |
      f.getName().matches("%") and
      not f.getName().matches("_%") and // Public functions
      source instanceof DataFlow::ParameterNode and
      source.getScope() = f
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(BinaryExpr b |
      b.getOp() instanceof Mod and
      (
        b.getLeft().(StringLiteral).getText() = "<!--%s-->" or
        b.getLeft().(StringLiteral).getText() = "<?%s?>"
      ) and
      sink.asExpr() = b.getRight()
    )
  }
}

module XmlInjectionFlow = TaintTracking::Global<XmlInjectionConfig>;
import XmlInjectionFlow::PathGraph

from XmlInjectionFlow::PathNode source, XmlInjectionFlow::PathNode sink
where XmlInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "XML formatting with user input from $@.", source.getNode(), "parameter"

/**
 * @name XML Injection via String Formatting
 * @description User input flowing into XML comments or processing instructions via string formatting can lead to XML injection.
 * @kind path-problem
 * @problem.severity error
 * @id py/xml-injection-formatting
 * @tags security
 *       external/cwe/cwe-091
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module XmlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Treat all parameters of functions in the package as potential sources (library context)
    exists(Function f |
      f.getScope().getEnclosingModule().getName().matches("et_xmlfile%") and
      source instanceof DataFlow::ParameterNode and
      source.getScope() = f
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(BinaryExpr fmt |
      fmt.getOp() instanceof Mod and
      fmt.getLeft().(StrConst).getText().regexpMatch(".*(<\\?|<!--).*") and
      sink.asExpr() = fmt.getRight()
    )
  }
}

module XmlInjectionFlow = TaintTracking::Global<XmlInjectionConfig>;
import XmlInjectionFlow::PathGraph

from XmlInjectionFlow::PathNode source, XmlInjectionFlow::PathNode sink
where XmlInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential XML injection from $@.", source.getNode(), "parameter"
